===================================================================
--- index.html
+++ index.html
@@ -16,4 +16,37 @@
 <aside class="side"><div class="side-head"><div class="eyebrow">ORDEN DEL SEÑOR</div><h1>Defiende el reino</h1><div class="subtitle">Los exploradores enemigos se acercan desde el este.</div></div><div class="status-card"><div class="status-row"><span>FORTALEZA</span><b id="castleText">100 / 100</b></div><div class="health"><i id="castleBar"></i></div><div class="status-row" style="margin:9px 0 0"><span>GUARNICIÓN</span><b id="armyText">2 lanceros</b></div></div><div class="section-title">CONSTRUYE · RECLUTA</div><div class="build-grid"><button class="action" data-mode="wall"><span class="ico">▰</span><strong>Muralla</strong><small>25 ◈ · 10 ▤</small></button><button class="action" data-mode="gate"><span class="ico">▥</span><strong>Puerta</strong><small>35 ◈ · 15 ▤</small></button><button class="action" data-mode="tower"><span class="ico">♜</span><strong>Torre arquera</strong><small>55 ◈ · 25 ▤</small></button><button class="action" data-mode="soldier"><span class="ico">⚔</span><strong>Reclutar lancero</strong><small>30 ◈ · 15 ✦</small></button><button class="action wide" data-mode="attack"><span class="ico">➤</span><strong>¡Ordenar ataque!</strong><small>Selecciona tus tropas y marca un objetivo</small></button></div><div class="tip"><strong>CONSEJO:</strong> Construye torres sobre la muralla. Selecciona a tus lanceros y haz clic en el campo para moverlos. Sobrevive a 5 oleadas para liberar el valle.</div></aside></main>
 <footer class="bottom"><div class="controls"><span class="key">Clic</span> seleccionar / colocar <span class="key">M</span> muralla <span class="key">T</span> torre <span class="key">Esc</span> cancelar</div><div class="wave"><span class="wave-mark">⚔</span><div class="wave-text"><b id="waveText">PREPARATIVOS</b><span id="waveSub">PRIMERA INCURSIÓN EN 25 SEG.</span></div></div><div class="objective">OBJETIVO &nbsp;<b id="objective">0 / 5 oleadas</b></div></footer>
 </div>
 <script>
+(()=>{'use strict';
+const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
+const COLS=20,ROWS=16,TW=36,TH=18;let W=0,H=0,dpr=1,origin={x:0,y:0};
+let gold=180,wood=120,food=90,castleHP=100,wave=0,waveTimer=25,units=[],enemies=[],buildings=[],particles=[],selected=[],mode='',gameOver=false,won=false,kills=0,soundOn=false,last=0,clock=0;
+const terrain=[],decor=[];const castle={x:3,y:7,hp:100,max:100};
+const key=(x,y)=>`${x},${y}`,inMap=(x,y)=>x>=0&&y>=0&&x<COLS&&y<ROWS;
+function seeded(n){let a=Math.sin(n*127.1+311.7)*43758.5453;return a-Math.floor(a)}
+for(let y=0;y<ROWS;y++)for(let x=0;x<COLS;x++){let v=seeded(x*71+y*17);terrain.push({x,y,c:v});if(v>.88&&x>6&&x<18&&!(y>4&&y<11))decor.push({x,y,type:v>.95?'pine':'bush',v})}
+function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(r.width*dpr);canvas.height=Math.floor(r.height*dpr);W=r.width;H=r.height;ctx.setTransform(dpr,0,0,dpr,0,0);origin.x=W/2-(COLS-ROWS)*TW/4;origin.y=H/2-(COLS+ROWS)*TH/4+20}
+new ResizeObserver(resize).observe(canvas);resize();
+function iso(x,y,z=0){return{x:origin.x+(x-y)*TW/2,y:origin.y+(x+y)*TH/2-z}}
+function tileAt(px,py){let a=(px-origin.x)/(TW/2),b=(py-origin.y)/(TH/2);let x=Math.floor((a+b)/2),y=Math.floor((b-a)/2);return{x,y}}
+function diamond(x,y,fill,stroke){const p=iso(x,y);ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x+TW/2,p.y+TH/2);ctx.lineTo(p.x,p.y+TH);ctx.lineTo(p.x-TW/2,p.y+TH/2);ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=.6;ctx.stroke()}}
+function rounded(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.stroke()}}
+function rect(x,y,w,h,color){ctx.fillStyle=color;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))}
+function text(s,x,y,color='#fff',size=10,align='center'){ctx.fillStyle=color;ctx.font=`bold ${size}px ui-monospace,monospace`;ctx.textAlign=align;ctx.fillText(s,x,y)}
+function world(){for(const t of terrain){let p=iso(t.x,t.y),c=['#59734b','#617b50','#5d764d','#58714b','#647c51'][Math.floor(t.c*5)];if(t.x<2||t.x>17||t.y<2||t.y>13)c=['#4b6749','#506e4d','#4c694a'][Math.floor(t.c*3)];diamond(t.x,t.y,c,'#6e8255');if(t.c>.76){rect(p.x-1,p.y+8,2,2,'#9b9b61');rect(p.x+6,p.y+11,2,1,'#849659')}}
+// creek along the far frontier
+ctx.globalAlpha=.8;for(let i=8;i<17;i++){let p=iso(i,1);ctx.fillStyle='#547d78';ctx.fillRect(p.x-3,p.y+8,7,3);ctx.fillStyle='#8caaa0';ctx.fillRect(p.x-1,p.y+9,3,1)}ctx.globalAlpha=1;
+for(const d of decor.sort((a,b)=>(a.x+a.y)-(b.x+b.y)))drawTree(d);
+// tiny meadow flowers
+for(let i=0;i<26;i++){let x=seeded(i+111)*COLS,y=seeded(i+333)*ROWS,p=iso(x,y);if(x>6&&x<17){rect(p.x,p.y+8,2,2,['#d5bb6a','#d7d0a0','#b9ac63'][i%3])}}
+}
+function drawTree(d){let p=iso(d.x,d.y),h=d.type==='pine'?18:11;rect(p.x-3,p.y+7,7,4,'#604633');if(d.type==='pine'){rect(p.x-1,p.y-h+9,3,h-4,'#31543a');rect(p.x-5,p.y-h+12,11,5,'#3b6542');rect(p.x-4,p.y-h+6,9,5,'#487348');rect(p.x-2,p.y-h+2,5,5,'#567b4a');rect(p.x-4,p.y-h+6,2,2,'#77905a')}else{rect(p.x-6,p.y-h+6,12,8,'#497148');rect(p.x-4,p.y-h+1,9,8,'#597b4b');rect(p.x-1,p.y-h,4,5,'#698753');rect(p.x-3,p.y-h+3,2,2,'#8e9b5b')}}
+function drawCastle(){let p=iso(castle.x,castle.y); // ground shadow
+ctx.fillStyle='#32453388';ctx.beginPath();ctx.ellipse(p.x+6,p.y+31,72,18,-.15,0,Math.PI*2);ctx.fill();
+// keep wall and towers
+rect(p.x-29,p.y-22,58,43,'#927b59');rect(p.x-25,p.y-18,50,37,'#d0b988');rect(p.x-28,p.y-22,56,7,'#eee0b9');for(let i=-25;i<28;i+=10)rect(p.x+i,p.y-26,5,5,'#e1d0a4');
+rect(p.x-37,p.y-29,15,51,'#ad9465');rect(p.x+22,p.y-29,15,51,'#ad9465');rect(p.x-40,p.y-33,21,8,'#e3cf9e');rect(p.x+19,p.y-33,21,8,'#e3cf9e');for(let x of [p.x-37,p.x+22]){rect(x+3,p.y-42,9,12,'#8f774f');rect(x+1,p.y-45,13,5,'#d9c392');rect(x+4,p.y-49,7,5,'#8b4e3e');}
+rect(p.x-7,p.y+3,14,18,'#553d2b');rect(p.x-4,p.y+1,8,2,'#bd8d4a');rect(p.x-22,p.y-13,6,9,'#354d4a');rect(p.x+16,p.y-13,6,9,'#354d4a');rect(p.x-1,p.y-15,3,4,'#aa6549');rect(p.x-1,p.y-11,3,3,'#e4b66a');rect(p.x+8,p.y-15,3,4,'#aa6549');rect(p.x+8,p.y-11,3,3,'#e4b66a');
+// fluttering banner
+rect(p.x-4,p.y-53,2,13,'#66533c');rect(p.x-2,p.y-52,11,6,'#a94e3d');rect(p.x+3,p.y-50,3,2,'#e9c66c');
+}

input.newString:
rect(p.x-2,p.y-52,11,6,'#a94e3d');rect(p.x+3,p.y-50,3,2,'#e9c66c');
}
function drawBuilding(b){let p=iso(b.x,b.y);if(b.type==='wall'||b.type==='gate'){// wall has visible stone cap and shaded front
rect(p.x-16,p.y+4,32,8,b.type==='gate'?'#76583c':'#71634d');rect(p.x-17,p.y-3,34,10,b.type==='gate'?'#b18c57':'#aaa080');rect(p.x-18,p.y-7,36,6,b.type==='gate'?'#dfc27e':'#d0c8a9');for(let i=-13;i<17;i+=9)rect(p.x+i,p.y-8,6,3,b.type==='gate'?'#edce88':'#e2dac0');rect(p.x-8,p.y+1,2,7,'#827760');rect(p.x+6,p.y+1,2,7,'#827760');if(b.type==='gate'){rect(p.x-8,p.y-1,16,12,'#604633');rect(p.x-6,p.y+1,12,10,'#80543a');rect(p.x-1,p.y+1,2,10,'#c89e55')}}else{ // crenellated archer tower
rect(p.x-16,p.y+4,32,11,'#71634d');rect(p.x-13,p.y-18,26,25,'#b29d73');rect(p.x-16,p.y-22,32,7,'#d7c79e');for(let i=-14;i<16;i+=9)rect(p.x+i,p.y-27,6,7,'#d7c79e');rect(p.x-7,p.y-10,14,9,'#354e4a');rect(p.x-5,p.y-8,10,7,'#27392f');rect(p.x-1,p.y-17,2,7,'#d5a750');rect(p.x-2,p.y-16,4,2,'#d8c493');if(b.hp<b.max){rect(p.x-12,p.y-31,24,3,'#493f31');rect(p.x-12,p.y-31,24*b.hp/b.max,3,'#9bba64')}}}
}
function drawUnit(u){let p=iso(u.x,u.y);ctx.fillStyle='#19241d88';ctx.beginPath();ctx.ellipse(p.x,p.y+9,7,3,0,0,Math.PI*2);ctx.fill();if(u.selected){ctx.strokeStyle='#f0d26c';ctx.lineWidth=1.5;ctx.beginPath();ctx.ellipse(p.x,p.y+8,11,5,0,0,Math.PI*2);ctx.stroke()}
let foe=u.side==='enemy',coat=foe?'#874f3e':'#477653',trim=foe?'#bd7651':'#9bc275';rect(p.x-3,p.y-1,6,7,coat);rect(p.x-4,p.y+5,3,4,'#463b32');rect(p.x+1,p.y+5,3,4,'#463b32');rect(p.x-3,p.y-7,6,6,'#d7ad7b');rect(p.x-4,p.y-8,8,3,foe?'#b55f45':'#b9944d');rect(p.x-3,p.y-2,2,3,trim);rect(p.x+2,p.y-1,2,4,trim);
// spear and pennon
rect(p.x+5,p.y-14,2,23,'#9a7247');rect(p.x+4,p.y-17,4,4,'#ddd1a9');rect(p.x+5,p.y-20,2,4,'#a9a28d');if(!foe&&u.selected){rect(p.x-2,p.y-4,2,3,'#e8c86b')}
if(u.hp<u.max){rect(p.x-7,p.y-12,14,2,'#342c26');rect(p.x-7,p.y-12,14*u.hp/u.max,2,foe?'#d37559':'#a9cb71')}}
function drawEnemy(e){drawUnit({...e,side:'enemy'})}
function draw(){if(!W||!H)return;ctx.clearRect(0,0,W,H);world();drawCastle();let all=[...buildings.map(b=>({...b,drawType:'b'})),...units.map(u=>({...u,drawType:'u'})),...enemies.map(e=>({...e,drawType:'e'}))].sort((a,b)=>(a.x+a.y)-(b.x+b.y));for(const o of all){if(o.drawType==='b')drawBuilding(o);else if(o.drawType==='u')drawUnit(o);else drawEnemy(o)}
// rally flag
if(rally){let p=iso(rally.x,rally.y);rect(p.x,p.y-19,2,19,'#6d563e');rect(p.x+2,p.y-19,9,6,'#d5ae59');rect(p.x+5,p.y-17,2,2,'#934b3e')}
for(const q of particles){ctx.globalAlpha=Math.max(0,q.life);text(q.label,q.x,q.y,q.color,10);ctx.globalAlpha=1}
if(mode&&mode!=='attack'){const t=pointer.tile;if(inMap(t.x,t.y)){let valid=canPlace(t.x,t.y,mode);diamond(t.x,t.y,valid?'#f0d26c66':'#e06b5666',valid?'#ffe08a':'#fa8873')}}
if(gameOver||won){ctx.fillStyle='#111a17bb';ctx.fillRect(0,0,W,H);rounded(W/2-145,H/2-50,290,100,4,'#202e27','#d6b45e');text(won?'¡EL VALLE ES TUYO!':'LA FORTALEZA HA CAÍDO',W/2,H/2-9,won?'#f2d375':'#ed8866',16);text(won?'Has repelido las cinco oleadas.':'Reúne tus fuerzas e inténtalo de nuevo.',W/2,H/2+17,'#d2d7bf',10);text('Pulsa R para volver a jugar',W/2,H/2+37,'#aeba9c',9)}
}
const pointer={x:0,y:0,tile:{x:-1,y:-1}};let rally=null;
function canPlace(x,y,type){if(!inMap(x,y)||x<2||x>17||y<2||y>13)return false;if(Math.abs(x-castle.x)+Math.abs(y-castle.y)<2)return false;if(decor.some(d=>Math.abs(d.x-x)<1&&Math.abs(d.y-y)<1))return false;if(buildings.some(b=>b.x===x&&b.y===y)||units.some(u=>Math.floor(u.x)===x&&Math.floor(u.y)===y)||enemies.some(e=>Math.floor(e.x)===x&&Math.floor(e.y)===y))return false;if(type==='tower'&& !buildings.some(b=>b.type==='wall'&&Math.abs(b.x-x)+Math.abs(b.y-y)===1))return false;return true}

