input.newString:
const pointer={x:0,y:0,tile:{x:-1,y:-1}};let rally=null;
const costs={wall:[25,10,0],gate:[35,15,0],tower:[55,25,0],soldier:[30,0,15]};
units.push({x:4.7,y:6.7,hp:40,max:40,side:'ally',selected:false,cd:0},{x:4.8,y:8.1,hp:40,max:40,side:'ally',selected:false,cd:.5});
function spend(type){const c=costs[type];if(gold<c[0]||wood<c[1]||food<c[2]){toast('No tienes suficientes recursos');return false}gold-=c[0];wood-=c[1];food-=c[2];return true}
let toastTimer;function toast(s){const el=document.getElementById('toast');el.textContent=s;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function setMode(m){mode=m;document.querySelectorAll('.action').forEach(b=>b.classList.toggle('active',b.dataset.mode===m));if(m==='attack')toast(selected.length?'Marca dónde deben avanzar tus lanceros':'Primero selecciona un lancero')}
function recruit(){if(!spend('soldier'))return;let n=units.length;units.push({x:castle.x+2.1+(n%2)*.5,y:castle.y-1.1+Math.floor(n/2)*.65,hp:40,max:40,side:'ally',selected:false,cd:Math.random()});toast('¡Un lancero se une a la guarnición!');updateUI()}
function buildAt(x,y,type){if(!canPlace(x,y,type)){toast(type==='tower'?'La torre necesita una muralla cercana':'Ese terreno no está disponible');return}if(!spend(type))return;buildings.push({x,y,type,hp:type==='tower'?85:110,max:type==='tower'?85:110});if(type==='gate')toast('Puerta de roble reforzada construida');else if(type==='tower')toast('¡Torre lista! Los arqueros dispararán automáticamente');else toast('Muralla colocada');updateUI()}
function spawnWave(){wave++;waveTimer=35+wave*3;for(let i=0;i<2+wave*2;i++){let y=5+Math.random()*6;enemies.push({x:18.3+Math.random()*.7,y,hp:wave>3?48:36,max:wave>3?48:36,side:'enemy',speed:.42+Math.random()*.08,cd:Math.random()*1,attack:8+wave});}document.getElementById('waveText').textContent=`OLEADA ${wave} · ${2+wave*2} SAQUEADORES`;document.getElementById('waveSub').textContent='¡LOS CUERNOS DE GUERRA RESUENAN!';toast(`¡Oleada ${wave}! Los saqueadores llegan del este`);if(wave===1)document.getElementById('weather').textContent='VIGILA EL ESTE';if(wave>=5)won=true}
function damageEnemy(e,amount){e.hp-=amount;particles.push({x:iso(e.x,e.y).x,y:iso(e.x,e.y).y-18,label:'✦',color:'#f0ce72',life:.8});if(e.hp<=0){enemies.splice(enemies.indexOf(e),1);gold+=8;food+=2;kills++;if(kills%4===0)wood+=6}}
function nearestEnemy(x,y,range){let best=null,dist=range;for(const e of enemies){let d=Math.hypot(e.x-x,e.y-y);if(d<dist){best=e;dist=d}}return best}
function update(dt){clock+=dt;if(!gameOver&&!won){waveTimer-=dt;if(waveTimer<=0)spawnWave();gold+=dt*.32;wood+=dt*.11;food+=dt*.12;
// towers fire automatically
