for(const u of [...units]){u.cd-=dt;if(u.order){let dx=u.order.x-u.x,dy=u.order.y-u.y,d=Math.hypot(dx,dy);if(d>.18){u.x+=dx/d*1.35*dt;u.y+=dy/d*1.35*dt}else u.order=null}if(u.cd<=0){let e=nearestEnemy(u.x,u.y,1.35);if(e){damageEnemy(e,15);u.cd=.75}}}
