let nearUnit=units.filter(u=>Math.hypot(u.x-e.x,u.y-e.y)<.9)[0];if(nearUnit){if(e.cd<=0){nearUnit.hp-=e.attack;e.cd=1.1;particles.push({x:iso(nearUnit.x,nearUnit.y).x,y:iso(nearUnit.x,nearUnit.y).y-15,label:'-'+e.attack,color:'#ed795d',life:.65});if(nearUnit.hp<=0){units.splice(units.indexOf(nearUnit),1);selected=selected.filter(u=>u!==nearUnit)}}continue}
let dx=target.x-e.x,dy=target.y-e.y,d=Math.hypot(dx,dy);if(d>.72){e.x+=dx/d*e.speed*dt;e.y+=dy/d*e.speed*dt}else if(e.cd<=0){castleHP-=e.attack;e.cd=1.3;particles.push({x:iso(castle.x,castle.y).x,y:iso(castle.x,castle.y).y-40,label:'-'+e.attack,color:'#fa7756',life:.8});if(castleHP<=0){castleHP=0;gameOver=true}}}
}
for(const p of particles){p.y-=18*dt;p.life-=dt}particles=particles.filter(p=>p.life>0);updateUI()}
function updateUI(){document.getElementById('gold').textContent=Math.floor(gold);document.getElementById('wood').textContent=Math.floor(wood);document.getElementById('food').textContent=Math.floor(food);document.getElementById('castleText').textContent=`${Math.ceil(castleHP)} / 100`;document.getElementById('castleBar').style.width=`${Math.max(0,castleHP)}%`;document.getElementById('armyText').textContent=`${units.length} lancero${units.length===1?'':'s'}`;document.getElementById('objective').textContent=`${Math.min(wave,5)} / 5 oleadas`;if(wave===0)document.getElementById('waveSub').textContent=`PRIMERA INCURSIÓN EN ${Math.max(0,Math.ceil(waveTimer))} SEG.`;else if(wave<5)document.getElementById('waveSub').textContent=`SIGUIENTE OLEADA EN ${Math.max(0,Math.ceil(waveTimer))} SEG.`}

