function canPlace(x,y,type){if(!inMap(x,y)||x<2||x>17||y<2||y>13)return false;if(Math.abs(x-castle.x)+Math.abs(y-castle.y)<2)return false;if(decor.some(d=>Math.abs(d.x-x)<1&&Math.abs(d.y-y)<1))return false;if(buildings.some(b=>b.x===x&&b.y===y)||units.some(u=>Math.floor(u.x)===x&&Math.floor(u.y)===y)||enemies.some(e=>Math.floor(e.x)===x&&Math.floor(e.y)===y))return false;if(type==='tower'&& !buildings.some(b=>b.type==='wall'&&Math.abs(b.x-x)+Math.abs(b.y-y)===1))return false;return true}
function pickTile(clientX,clientY){const r=canvas.getBoundingClientRect(),px=clientX-r.left,py=clientY-r.top;pointer.x=px;pointer.y=py;const a=(px-origin.x)/(TW/2),b=(py-origin.y-TH/2)/(TH/2);pointer.tile={x:Math.round((a+b)/2),y:Math.round((b-a)/2)}}
canvas.addEventListener('pointermove',e=>pickTile(e.clientX,e.clientY));
canvas.addEventListener('pointerdown',e=>{if(e.button!==0)return;pickTile(e.clientX,e.clientY);let{x,y}=pointer.tile;if(!inMap(x,y))return;
if(mode==='wall'||mode==='gate'||mode==='tower'){buildAt(x,y,mode);return}
if(mode==='attack'){if(!selected.length){toast('Selecciona primero a tus lanceros');setMode('');return}rally={x,y};selected.forEach(u=>u.order={x:x+.2,y:y+.2});toast('¡Avanzad, lanceros!');setMode('');return}
const hitUnit=units.find(u=>Math.hypot(u.x-x,u.y-y)<.9),hitEnemy=enemies.find(u=>Math.hypot(u.x-x,u.y-y)<.9);
if(hitUnit){hitUnit.selected=!hitUnit.selected;selected=units.filter(u=>u.selected);if(selected.length)toast(`${selected.length} lancero${selected.length===1?'':'s'} seleccionado${selected.length===1?'':'s'}`);updateUI();return}
if(hitEnemy&&selected.length){selected.forEach(u=>u.order={x:hitEnemy.x,y:hitEnemy.y});toast('¡A por los saqueadores!');return}
if(selected.length){rally={x,y};selected.forEach(u=>u.order={x:x+.2,y:y+.2});toast('Lanceros en marcha');return}selected=[];units.forEach(u=>u.selected=false);
});
document.querySelectorAll('.action').forEach(button=>button.addEventListener('click',()=>{const m=button.dataset.mode;if(m==='soldier'){setMode('');recruit()}else if(m==='attack'){setMode(mode==='attack'?'':'attack')}else setMode(mode===m?'':m)}));
document.getElementById('sound').addEventListener('click',e=>{soundOn=!soundOn;e.currentTarget.textContent=soundOn?'♫ SONIDO':'♪ SONIDO';toast(soundOn?'Sonido activado':'Sonido desactivado')});
function restart(){gold=180;wood=120;food=90;castleHP=100;wave=0;waveTimer=25;gameOver=false;won=false;kills=0;units.splice(0);enemies.splice(0);buildings.splice(0);particles.splice(0);units.push({x:4.7,y:6.7,hp:40,max:40,side:'ally',selected:false,cd:0},{x:4.8,y:8.1,hp:40,max:40,side:'ally',selected:false,cd:.5});selected=[];rally=null;setMode('');document.getElementById('waveText').textContent='PREPARATIVOS';document.getElementById('weather').textContent='CIELO CLARO';updateUI();toast('La defensa comienza de nuevo')}
window.addEventListener('keydown',e=>{if(e.key==='Escape'){setMode('');selected=[];units.forEach(u=>u.selected=false)}else if(e.key.toLowerCase()==='m')setMode(mode==='wall'?'':'wall');else if(e.key.toLowerCase()==='t')setMode(mode==='tower'?'':'tower');else if(e.key.toLowerCase()==='g')setMode(mode==='gate'?'':'gate');else if(e.key.toLowerCase()==='r'&&(gameOver||won))restart()});
function frame(now){let dt=Math.min(.05,(now-last)/1000||0);last=now;update(dt);draw();requestAnimationFrame(frame)}updateUI();requestAnimationFrame(frame);
})();
</script>
</body>
</html>

